CREATE DEFINER=`vuaduoc`@`localhost` PROCEDURE `fe_bai_viet_theo_chuyen_muc` (`p_cat_id` BIGINT, `p_page` INT, `p_number_items` INT)   BEGIN

	Set @v_str_sql = concat(' SELECT *
		FROM posts
		WHERE pos_category_id = ',p_cat_id,'
		AND pos_active = 1
		AND pos_deleted_at IS NULL
		ORDER BY pos_created_at DESC');

	-- Phan trang
	SET @v_str_sql = CONCAT(@v_str_sql, ' LIMIT ', (p_page - 1) * p_number_items, ',', p_number_items);

	PREPARE stmt1 FROM @v_str_sql;
	EXECUTE stmt1;
	DEALLOCATE PREPARE stmt1;

END$$

