CREATE DEFINER=`vuaduoc`@`localhost` PROCEDURE `fe_san_pham_theo_chuyen_muc` (`p_cat_id` BIGINT, `p_page` INT, `p_number_items` INT)   BEGIN

	Set @v_str_sql = concat(' SELECT *,
		(SELECT pri_file_name FROM products_images WHERE pri_product_id = pro_id AND pri_is_avatar = 1 LIMIT 1) file_name_img
		FROM products
		WHERE pro_category_id = ',p_cat_id,'
		AND pro_active = 1
		AND pro_deleted_at IS NULL
		ORDER BY pro_order_by ASC');

	-- Phan trang
	SET @v_str_sql = CONCAT(@v_str_sql, ' LIMIT ', (p_page - 1) * p_number_items, ',', p_number_items);

	PREPARE stmt1 FROM @v_str_sql;
	EXECUTE stmt1;
	DEALLOCATE PREPARE stmt1;

END$$

