--
-- Table structure for table `warehouse`
--

CREATE TABLE `warehouse` (
  `who_id` int NOT NULL COMMENT 'ID phiếu nhập',
  `who_pro_id` int NOT NULL COMMENT 'ID của sản phẩm',
  `who_product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên Sản phẩm',
  `who_import_date` datetime DEFAULT NULL COMMENT 'Ngày nhập',
  `who_product_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Loại nhập',
  `who_note` text COLLATE utf8mb4_unicode_ci COMMENT 'Ghi chú',
  `who_quantity` int DEFAULT '0' COMMENT 'Số lượng sp Nhập',
  `who_quantity_available` int DEFAULT '0' COMMENT 'Số lượng khả dụng',
  `who_quantity_packing` int DEFAULT '0' COMMENT 'Số lượng PKiện',
  `who_carton_quantity` int DEFAULT '0' COMMENT 'Số lượng kiện/thùng',
  `who_unit_price` decimal(18,2) DEFAULT '0.00' COMMENT 'Giá nhập',
  `who_other_cost` decimal(18,2) DEFAULT '0.00' COMMENT 'Chi phí khác',
  `who_total_price` decimal(18,2) DEFAULT '0.00' COMMENT 'Tổng nhập',
  `who_packaging_unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Đơn vị đóng gói (chai, hộp, gói...)',
  `who_supplier_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nhà cung cấp (NCC) - Mã',
  `who_supplier_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Tên nhà cung cấp',
  `who_receiver_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Người nhận hàng',
  `who_warehouse_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kho nhận',
  `who_lot_number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Số lô/LOT',
  `who_mfg_date` datetime DEFAULT NULL COMMENT 'Ngày sản xuất (MFG)',
  `who_exp_date` datetime DEFAULT NULL COMMENT 'Hạn dùng EXP',
  `who_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'pending' COMMENT 'Trạng thái: pending, completed, cancelled',
  `who_created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Người tạo phiếu',
  `who_created_date` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Ngày tạo',
  `who_updated_date` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'Ngày cập nhật'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bảng quản lý nhập kho';

